const crypto = require('crypto');

// HMAC-SHA256 over `${timestamp}\n${method}\n${path}\n${body}`, verified by
// convex/http.ts. The path is part of the MAC, so the signature is only valid
// for the endpoint it was made for. The HTTP node posts to the returned `url`,
// so the path signed and the path called can't drift apart.
function signForLendLoop(path, payload) {
  const secret = $env.N8N_TO_LENDLOOP_SECRET;
  const baseUrl = $env.CONVEX_SITE_URL;
  if (!secret) throw new Error('N8N_TO_LENDLOOP_SECRET is not configured');
  if (!baseUrl) throw new Error('CONVEX_SITE_URL is not configured');
  const body = JSON.stringify(payload);
  const timestamp = String(Math.floor(Date.now() / 1000));
  const mac = crypto.createHmac('sha256', secret).update([timestamp, 'POST', path, body].join('\n')).digest('hex');
  return { url: baseUrl.replace(/\/+$/, '') + path, body, timestamp, signature: `v2=${mac}` };
}

// Error Trigger data differs for execution vs trigger failures; handle both.
const e = $input.first().json;
const execution = e.execution || {};
const executionId = String(execution.id || (e.trigger && e.trigger.id) || `trigger-${Date.now()}`);
const error = execution.error || (e.trigger && e.trigger.error) || {};
// Error messages can echo payloads; strip email addresses before they leave n8n.
const message = String(error.message || 'Unknown error')
  .replace(/[^\s@]+@[^\s@]+/g, '[email]')
  .slice(0, 500);

console.error(`[lendloop] workflow "${e.workflow && e.workflow.name}" failed at ${execution.lastNodeExecuted}: ${message}`);

return [{
  json: signForLendLoop('/n8n/workflow-errors', {
    executionId,
    workflowName: String((e.workflow && e.workflow.name) || 'unknown workflow').slice(0, 100),
    ...(execution.lastNodeExecuted ? { nodeName: String(execution.lastNodeExecuted).slice(0, 100) } : {}),
    message,
  }),
}];
